// Create a new JBIG2 decoder context using the public entry point macro jbig2_ctx_new
// to ensure correct library version numbers are supplied by the macro.
// We keep API usage simple and valid: use default allocator (NULL), normal mode (options=0),
// no global context (NULL), and either a default or a simple captureless error callback.

// Option flags: use 0 (no embedded mode) to avoid requiring a global context.
Jbig2Options opts = (Jbig2Options)0;

// Choose whether to supply an explicit error callback or use default (NULL)
unsigned int use_custom_cb = *FUZZ_PARAM(unsigned int) % 2;
Jbig2ErrorCallback err_cb = nullptr;
if (use_custom_cb) {
    // Minimal no-op callback to exercise the callback path without side-effects.
    err_cb = +[](void *user, const char *msg, Jbig2Severity sev, uint32_t seg){ (void)user; (void)msg; (void)sev; (void)seg; };
}

void *err_user = nullptr; // Opaque data may be NULL per API.
Jbig2GlobalCtx *gctx = nullptr; // Not using embedded decoding here.
Jbig2Allocator *allocator = nullptr; // Use default malloc-based allocator.

Jbig2Ctx *ctx = jbig2_ctx_new(allocator, opts, gctx, err_cb, err_user);
if (!ctx) { FUZZ_BAIL(); }

// Track state on the context for downstream stubs.
FUZZ_SET_ATTR_INT(ctx, "open_images", 0);
// ctx is provided as an output and remains owned by the API until freed.

// Validation: We ensure macro-based creation with valid defaults and record open_images=0 for lifetime tracking.

// Free a previously created JBIG2 decoder context.
// Enforce that no unreleased images remain to avoid violating API requirements.
int open_images = FUZZ_GET_ATTR_INT(ctx, "open_images");
if (open_images != 0) { FUZZ_BAIL(); }

// Free the context; returned allocator (if any) remains owned by the caller, but we do not persist it.
Jbig2Allocator *ret_alloc = jbig2_ctx_free(ctx);
(void)ret_alloc; // Not persisted; runtime drops it.

// Validation: We bail if there are outstanding images and otherwise free ctx, matching ownership rules.

// Create a global context from an existing decoder context.
Jbig2GlobalCtx *global_ctx = jbig2_make_global_ctx(ctx);
if (!global_ctx) { FUZZ_BAIL(); }

// Track parent relationship for validation/use by other stubs if needed.
FUZZ_SET_ATTR_PTR(global_ctx, "parent_ctx", ctx);

// Output both ctx (still alive) and the new global context.

// Validation: We verify successful creation and bind the global_ctx to its parent ctx via attributes.

// Free a previously created global context.
// Optionally validate basic provenance (if parent was tracked), but allow freeing regardless.
(void)FUZZ_GET_ATTR_PTR(global_ctx, "parent_ctx");
Jbig2Allocator *ret_alloc = jbig2_global_ctx_free(global_ctx);
(void)ret_alloc;

// Validation: We simply free the global context and do not return any outputs, avoiding reuse after free.

// Feed raw data into the decoder.
// Generate a fuzz buffer; ensure size is reasonable (<2048 bytes) for performance.
std::string buf = FUZZ_PARAM_STR();
size_t max_feed = 2048;
size_t feed = buf.size() > max_feed ? max_feed : buf.size();
const unsigned char *p = reinterpret_cast<const unsigned char*>(buf.data());

int rc = jbig2_data_in(ctx, p, feed);
(void)rc; // Return code unknown; caller may ignore or check separately.

// Track cumulative fed bytes as a soft metric.
int fed = FUZZ_GET_ATTR_INT(ctx, "fed_bytes");
FUZZ_SET_ATTR_INT(ctx, "fed_bytes", fed + (int)feed);

// Return ctx to keep it alive.

// Validation: We respect buffer validity and size constraints, and preserve ctx for subsequent calls.

// Attempt to retrieve the next decoded page image.
Jbig2Image *image = jbig2_page_out(ctx);
// To ensure outputs are never null and to enable separate release testing,
// bail out when no page is available.
if (!image) { FUZZ_BAIL(); }

// Track ownership and parent relation for validation in release.
FUZZ_SET_ATTR_PTR(image, "parent_ctx", ctx);

// Maintain a count of outstanding images on the ctx to prevent invalid frees.
int open_images = FUZZ_GET_ATTR_INT(ctx, "open_images");
FUZZ_SET_ATTR_INT(ctx, "open_images", open_images + 1);

// Provide both ctx (still in use) and the acquired image.

// Validation: We enforce non-null image, link it to ctx, and update open_images for lifecycle checks.

// Release a page previously obtained from jbig2_page_out for the same ctx.
Jbig2Ctx *parent = (Jbig2Ctx *)FUZZ_GET_ATTR_PTR(image, "parent_ctx");
if (parent != ctx) { FUZZ_BAIL(); }

jbig2_release_page(ctx, image);

// Decrement open image count on the context.
int open_images = FUZZ_GET_ATTR_INT(ctx, "open_images");
// open_images should be >0 here given we had an image; assert property to catch inconsistencies.
FUZZ_ASSERT(open_images > 0, "open_images must be positive when releasing an image");
FUZZ_SET_ATTR_INT(ctx, "open_images", open_images - 1);

// Do not return the image; it is released. Return ctx to keep it alive.

// Validation: We ensure image belongs to ctx, release it, and update lifecycle counters.

// Mark the current page as complete; return code semantics are unknown.
int rc = jbig2_complete_page(ctx);
(void)rc;

